import { api } from './api.js';
import { challengeDefinitions, cloneDefault, evaluateChallenge, evaluateSecret, logicOutput, balanceMoments, simulateJump, physicsTarget, stepDoor } from './challenge-engine.js';

const guestStorageKey = 'skillverse-guest-progress';
const challengeStorageKey = 'skillverse-challenges';
const guestDefaults = () => ({ completedLessonIds: [], solvedExerciseIds: [], totalXp: 0, activityDates: [] });
function loadGuestProgress() {
  try {
    const saved = JSON.parse(localStorage.getItem(guestStorageKey) || 'null');
    if (!saved || typeof saved !== 'object') return guestDefaults();
    return {
      completedLessonIds: Array.isArray(saved.completedLessonIds) ? saved.completedLessonIds.map(Number).filter(Number.isFinite) : [],
      solvedExerciseIds: Array.isArray(saved.solvedExerciseIds) ? saved.solvedExerciseIds.map(Number).filter(Number.isFinite) : [],
      totalXp: Number.isFinite(Number(saved.totalXp)) ? Number(saved.totalXp) : 0,
      activityDates: Array.isArray(saved.activityDates) ? saved.activityDates.filter((date) => typeof date === 'string') : []
    };
  } catch { return guestDefaults(); }
}
const app = document.querySelector('#app');
const escapeHtml = (value) => String(value ?? '').replace(/[&<>'"]/g, (char) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', "'": '&#039;', '"': '&quot;' })[char]);
function storedFlag(key) { try { return localStorage.getItem(key) === 'true'; } catch { return false; } }
function saveStoredFlag(key, value) { try { localStorage.setItem(key, String(value)); } catch { /* La preferencia es opcional y no debe romper la navegación. */ } }
const formatDate = (value) => value ? new Intl.DateTimeFormat('es', { day: 'numeric', month: 'short', year: 'numeric' }).format(new Date(value)) : '—';
const progressFor = (id) => state.progress.find((item) => Number(item.lesson_id) === Number(id)) || (!state.user && state.guest.completedLessonIds.includes(Number(id)) ? { lesson_id: Number(id), status: 'completed' } : null);
const toast = (message, kind = '') => { const region = document.querySelector('#toast-region'); const item = document.createElement('div'); item.className = `toast ${kind}`; item.textContent = message; region.append(item); setTimeout(() => item.remove(), 4200); };
const loading = (label = 'Preparando tu siguiente descubrimiento…') => `<div class="container loading"><span class="pulse"></span>${label}</div>`;
const guestProgressRows = () => state.guest.completedLessonIds.map((lesson_id) => ({ lesson_id, status: 'completed' }));
const guestToday = () => new Date().toISOString().slice(0, 10);
function saveGuestProgress() { try { localStorage.setItem(guestStorageKey, JSON.stringify(state.guest)); } catch { /* El progreso visual sigue funcionando aunque el almacenamiento esté bloqueado. */ } }
function touchGuestActivity() { const today = guestToday(); if (!state.guest.activityDates.includes(today)) state.guest.activityDates.push(today); }
function guestStats() { const completedLessons = state.guest.completedLessonIds.length; const solvedExercises = state.guest.solvedExerciseIds.length + (state.challengeProgress?.completedSlugs?.length || 0); return { total_xp: state.guest.totalXp, current_level: state.guest.totalXp >= 900 ? 'Arquitecto digital' : state.guest.totalXp >= 500 ? 'Desarrollador' : state.guest.totalXp >= 250 ? 'Constructor de código' : state.guest.totalXp >= 100 ? 'Aprendiz lógico' : 'Explorador', current_streak: state.guest.activityDates.length ? 1 : 0, completed_lessons: completedLessons, solved_exercises: solvedExercises }; }
function guestAchievements() { const stats = guestStats(); return [{ id: 1, name: 'Primer paso', description: 'Completa tu primera lección.', icon: '✦', unlocked: stats.completed_lessons >= 1 }, { id: 2, name: 'Mente lógica', description: 'Resuelve diez ejercicios correctamente.', icon: '⌘', unlocked: stats.solved_exercises >= 10 }, { id: 3, name: 'Constancia', description: 'Estudia en tres días distintos.', icon: '◒', unlocked: state.guest.activityDates.length >= 3 }, { id: 4, name: 'Cazador de errores', description: 'Supera un ejercicio de detección de errores.', icon: '⌁', unlocked: false }, { id: 5, name: 'Constructor', description: 'Completa tu primer proyecto.', icon: '◆', unlocked: false }]; }
function validateGuestExercise(id, answer) { const value = String(answer || '').trim().toLowerCase(); const choices = { 1: 'pasos', 2: 'datos', 4: '===', 5: 'if', 7: 'return', 8: '0', 9: 'probar', 11: 'texto' }; if (choices[Number(id)]) return value === choices[Number(id)]; const code = value.replace(/\s+/g, ' '); if (Number(id) === 3) return /\b(?:let|const|var)\s+edad\s*=\s*18\b/.test(code); if (Number(id) === 6) return /for\s*\(/.test(code) && /\bi\b/.test(code) && /(?:<=|<)\s*3/.test(code); if (Number(id) === 10) return /function\s+mensaje\s*\(\s*nombre\s*\)/.test(code); return false; }
function guestExerciseAttempt(exercise, answer) { const isCorrect = validateGuestExercise(exercise.id, answer); const alreadyRewarded = state.guest.solvedExerciseIds.includes(Number(exercise.id)); if (isCorrect && !alreadyRewarded) { state.guest.solvedExerciseIds.push(Number(exercise.id)); state.guest.totalXp += Number(exercise.xp_reward) || 0; touchGuestActivity(); saveGuestProgress(); } return { isCorrect, alreadyRewarded, xpAwarded: isCorrect && !alreadyRewarded ? Number(exercise.xp_reward) || 0 : 0, feedback: isCorrect ? (alreadyRewarded ? 'Respuesta correcta. La experiencia de este ejercicio ya estaba registrada en este navegador.' : exercise.feedback) : 'Todavía no. Revisa la pista y prueba otra vez.', hint: isCorrect ? null : exercise.hint }; }
function completeGuestLesson(id) { const lessonId = Number(id); const alreadyCompleted = state.guest.completedLessonIds.includes(lessonId); if (!alreadyCompleted) { state.guest.completedLessonIds.push(lessonId); state.guest.totalXp += 20; touchGuestActivity(); saveGuestProgress(); } return { alreadyCompleted, stats: guestStats() }; }
function loadChallengeProgress() { try { const saved = JSON.parse(localStorage.getItem(challengeStorageKey) || 'null'); if (!saved || typeof saved !== 'object') return { completedSlugs: [], bestScores: {}, drafts: {} }; return { completedSlugs: Array.isArray(saved.completedSlugs) ? saved.completedSlugs.filter((slug) => challengeDefinitions.some((challenge) => challenge.slug === slug)) : [], bestScores: saved.bestScores && typeof saved.bestScores === 'object' ? saved.bestScores : {}, drafts: saved.drafts && typeof saved.drafts === 'object' ? saved.drafts : {} }; } catch { return { completedSlugs: [], bestScores: {}, drafts: {} }; } }
function saveChallengeProgress() { try { localStorage.setItem(challengeStorageKey, JSON.stringify(state.challengeProgress)); } catch { /* El reto sigue funcionando aunque el almacenamiento esté bloqueado. */ } }
function challengeDefinition(slug) { return challengeDefinitions.find((challenge) => challenge.slug === slug); }
function challengeDraft(slug) { const definition = challengeDefinition(slug); const saved = state.challengeProgress.drafts[slug]; return definition ? { ...cloneDefault(slug), ...(saved || {}) } : null; }
function saveChallengeDraft(slug, draft) { state.challengeProgress.drafts[slug] = draft; saveChallengeProgress(); }
function completeChallenge(slug, xp) { const alreadyCompleted = state.challengeProgress.completedSlugs.includes(slug); if (!alreadyCompleted) { state.challengeProgress.completedSlugs.push(slug); state.challengeProgress.bestScores[slug] = 100; state.guest.totalXp += xp; touchGuestActivity(); saveGuestProgress(); saveChallengeProgress(); } return { alreadyCompleted }; }

const state = { user: null, courses: [], route: '/', query: new URLSearchParams(), course: null, lessons: [], lesson: null, exercise: null, stats: null, progress: [], achievements: [], courseFilter: 'Todos', courseSearch: '', guest: loadGuestProgress(), challengeProgress: loadChallengeProgress() };

const legacyRoutes = { home: '/', courses: '/cursos', challenges: '/retos', lab: '/laboratorio', progress: '/progreso', achievements: '/logros', leaderboard: '/clasificacion', profile: '/perfil', pricing: '/planes', auth: '/login', dashboard: '/panel', admin: '/admin', privacy: '/privacidad', terms: '/terminos' };

function normalizeRoute() {
  if (!location.hash) return;
  const raw = location.hash.slice(1);
  const [legacyPath, query] = raw.split('?');
  if (!legacyRoutes[legacyPath] && legacyPath !== 'learning') return;
  let target = legacyRoutes[legacyPath] || `/${legacyPath}`;
  if (legacyPath === 'auth' && new URLSearchParams(query || '').get('mode') === 'register') target = '/registro';
  if (legacyPath === 'learning') {
    const params = new URLSearchParams(query || '');
    target = params.get('lesson') ? `/lecciones/${params.get('lesson')}` : `/cursos/${params.get('course') || 1}`;
  }
  history.replaceState({}, '', `${target}${query && legacyPath !== 'learning' ? `?${query}` : ''}`);
}

function routeInfo() {
  const url = new URL(location.href);
  let path = url.pathname.replace(/\/+/g, '/');
  if (path.length > 1) path = path.replace(/\/$/, '');
  return { path: path || '/', query: url.searchParams, segments: (path || '/').split('/').filter(Boolean) };
}

function setRoute(path) {
  const [target, query] = path.split('?');
  const normalized = target || '/';
  if (`${location.pathname}${location.search}` !== `${normalized}${query ? `?${query}` : ''}`) history.pushState({}, '', `${normalized}${query ? `?${query}` : ''}`);
  window.scrollTo(0, 0);
  return renderRoute();
}

function isProtected() { return false; }
function updateNavigation(path) {
  const active = path.startsWith('/cursos/') || path.startsWith('/lecciones/') ? '/cursos' : path.startsWith('/retos/') || path === '/laboratorio' ? '/retos' : ['/progreso', '/logros'].includes(path) ? '/panel' : path;
  document.querySelectorAll('[data-route]').forEach((item) => item.classList.toggle('active', item.dataset.route === active));
  const auth = document.querySelector('#nav-auth');
  if (!auth) return;
  auth.innerHTML = state.user
    ? `${state.user.role === 'admin' ? '<a href="/admin" data-route="/admin">Admin</a>' : ''}<a href="/perfil" data-route="/perfil">${escapeHtml(state.user.username)}</a><button class="button button-ghost button-small" type="button" data-action="logout">Salir</button>`
    : '<a class="button button-ghost button-small" href="/login">Entrar</a><a class="button button-accent button-small" href="/registro">Crear cuenta</a>';
  auth.querySelectorAll('[data-route]').forEach((item) => item.classList.toggle('active', item.dataset.route === active));
}
function resetUserData() { state.stats = null; state.progress = []; state.achievements = []; }

