function courseCard(course, index = 0) { return `<article class="card course-card"><div class="course-meta"><span class="course-icon">${iconForCourse(index)}</span><span>${escapeHtml(course.difficulty)}</span>${Number(course.is_premium) ? '<span class="premium-tag">Premium</span>' : ''}</div><h3>${escapeHtml(course.title)}</h3><p>${escapeHtml(course.description)}</p><div class="course-meta"><span>${course.estimated_minutes} min</span><span>·</span><span>${Number(course.is_premium) ? 'Ruta ampliada' : 'Acceso abierto'}</span></div><a class="button button-secondary button-small" href="/cursos/${course.id}">Ver ruta <span aria-hidden="true">→</span></a></article>`; }

